entries[305394] = { ["name"] = "Absolute Freiheit", ["text"] = "'Segen der Freiheit' erhöht die Bewegungsgeschwindigkeit um 30% und Ihr erhaltet 'Segen der Freiheit', wenn Ihr ihn auf ein verbündetes Ziel wirkt." }
