entries[305578] = { ["name"] = "Leerenritual", ["text"] = "100 Energie\nWirken in 3 sek.\nXanesh öffnet Risse in die Leere, durch die mehrere Spielercharaktere ' Leerengeweckt ' werden, und beschwört eine Kugel, die sich auf Königin Azshara zubewegt.\n\nSpielercharaktere, die ' Leerengeweckt ' sind, können die Kugel in ihre Blickrichtung umlenken, indem sie darauf treffen.\n\nWenn die Kugel einen offenen Riss erreicht, wird sie zurück in die Leere geschickt.\n\nTrifft die Kugel auf einen Spielercharakter, der nicht ' Leerengeweckt ' ist, wird dieser von ' Schmähen ' getroffen. Wenn die Kugel auf Königin Azshara, einen Ritualobelisken oder die Wände des Raums trifft, löst sie ' Dunkler Kollaps ' aus und fügt so allen Spielercharakteren 60 Schattenschaden zu." }
entries[305579] = { ["name"] = "Leerenkugel beschwören", ["text"] = "500 Meter Reichweite\nWirken in 7 sek.\nXanesh führt ein Ritual durch, an dem 3 Spielercharaktere willentlich teilnehmen müssen. Wenn weniger als 3 Spielercharaktere teilnehmen, fügt Xanesh allen Spielercharakteren 93881 Schattenschaden zu.\n\nTeilnehmende Spielercharaktere werden ' Leerengeweckt '.\n\nBei Abschluss des Rituals wird eine Leerenkugel beschwört." }
