entries[305992] = { ["name"] = "Unvergleichlicher Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nZin'anthide (300), Ankerkraut (100), Expulsom (60)\nStellt einen unvergleichlichen Alchemistenstein her.\nBeruf:\nAlchemie von Battle for Azeroth (165)\nEntdeckung:\nErweckter Alchemistenstein\n\nUnvergleichlicher Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 16 Vielseitigkeit\n\nPrismatischer Sockel\n\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 42 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n50\nBenötigt Alchemie von Kul Tiras\n(175)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[305993] = { ["name"] = "Erweckter Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nZin'anthide (225), Ankerkraut (80), Expulsom (40)\nStellt einen erweckten Alchemistenstein her.\nBeruf:\nAlchemie von Battle for Azeroth (165)\nEntdeckung:\nEntfesselter Alchemistenstein\n\nErweckter Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 14 Vielseitigkeit\n\nPrismatischer Sockel\n\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 36 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n50\nBenötigt Alchemie von Kul Tiras\n(170)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[305994] = { ["name"] = "Entfesselter Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nZin'anthide (175), Ankerkraut (60), Expulsom (30)\nStellt einen entfesselten Alchemistenstein her.\nBeute von:\nKultisten von N'Zoth\n\nEntfesselter Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+ 12 Vielseitigkeit\n\nPrismatischer Sockel\n\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 31 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Kul Tiras\n(165)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
